/// Basic usage
///
/// ```rust
/// use tokio_util::time::DelayQueue;
/// use std::time::Duration;
///
/// # #[tokio::main]
/// # async fn main() {
/// let mut delay_queue = DelayQueue::new();
/// let key = delay_queue.insert("foo", Duration::from_secs(5));
///
/// // Remove the entry
/// let item = delay_queue.remove(&key);
/// assert_eq!(*item.get_ref(), "foo");
/// # }
/// ```
#[track_caller]
pub fn remove(&mut self, key: &Key) -> Expired<T> {
    use crate::time::wheel::Stack as WheelStack;

    let prev_deadline = self.next_deadline();

    if self.key_is_expired(key) {
        self.remove_from_expired(key);
    } else {
        let when = <Stack<T> as WheelStack>::when(key, &self.slab);
        assert!(
            self.wheel.elapsed <= when,
            "elapsed={}; when={}",
            self.wheel.elapsed,
            when
        );

        let level_idx = self.wheel.level_for(when);
        let level = &mut self.wheel.levels[level_idx];
        let slot = ((when >> (level.level * 6)) % 64) as usize;
        level.slot[slot].remove(key, &mut self.slab);

        if level.slot[slot].is_empty() {
            debug_assert!(level.occupied & (1u64 << slot) != 0);
            level.occupied ^= 1u64 << slot;
        }
    }

    let data = self.take_stored(key);
    self.sync_delay(prev_deadline);
    self.into_expired(key, data)
}

/// Attempts to remove the item associated with `key` from the queue.
///
/// Removes the item associated with `key`, and returns it along with the
/// `Instant` at which it would have expired, if it exists.
///
/// Returns `None` if `key` is not in the queue.
///
/// # Examples
///
/// Basic usage
///
/// ```rust
/// use tokio_util::time::DelayQueue;
/// use std::time::Duration;
///
/// # #[tokio::main(flavor = "current_thread")]
/// # async fn main() {
/// let mut delay_queue = DelayQueue::new();
/// let key = delay_queue.insert("foo", Duration::from_secs(5));
///
/// // The item is in the queue, `try_remove` returns `Some(Expired("foo"))`.
/// let item = delay_queue.try_remove(&key);
/// assert_eq!(item.unwrap().into_inner(), "foo");
///
/// // The item is not in the queue anymore, `try_remove` returns `None`.
/// let item = delay_queue.try_remove(&key);
/// assert!(item.is_none());
/// # }
/// ```
pub fn try_remove(&mut self, key: &Key) -> Option<Expired<T>> {
    if self.slab.contains(key) {
        Some(self.remove(key))
    } else {
        None
    }
}

